package com.sekai.world.simulation.model;

public class WorldRule {
    private Long id; private Long worldId; private String code; private String name; private String conditionType; private Integer thresholdValue; private String effectType; private Integer effectValue; private Integer priority; private Boolean enabled;
    public WorldRule() {} public WorldRule(Long id,Long worldId,String code,String name,String conditionType,Integer thresholdValue,String effectType,Integer effectValue,Integer priority,Boolean enabled){this.id=id;this.worldId=worldId;this.code=code;this.name=name;this.conditionType=conditionType;this.thresholdValue=thresholdValue;this.effectType=effectType;this.effectValue=effectValue;this.priority=priority;this.enabled=enabled;}
    public Long getId(){return id;} public void setId(Long v){id=v;} public Long getWorldId(){return worldId;} public void setWorldId(Long v){worldId=v;} public String getCode(){return code;} public void setCode(String v){code=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getConditionType(){return conditionType;} public void setConditionType(String v){conditionType=v;} public Integer getThresholdValue(){return thresholdValue;} public void setThresholdValue(Integer v){thresholdValue=v;} public String getEffectType(){return effectType;} public void setEffectType(String v){effectType=v;} public Integer getEffectValue(){return effectValue;} public void setEffectValue(Integer v){effectValue=v;} public Integer getPriority(){return priority;} public void setPriority(Integer v){priority=v;} public Boolean getEnabled(){return enabled;} public void setEnabled(Boolean v){enabled=v;}
    public Long id(){return id;} public Long worldId(){return worldId;} public String code(){return code;} public String name(){return name;} public String conditionType(){return conditionType;} public Integer thresholdValue(){return thresholdValue;} public String effectType(){return effectType;} public Integer effectValue(){return effectValue;} public Integer priority(){return priority;} public Boolean enabled(){return enabled;}
}
